code.java:
class Solution {
    public int fib(int n){
        int first=0,second=1;
        for(int i=0;i<n;i++){
            int next=first+second;
            first=second;
            second=next;
        }
        return first;
    }
}

code.kotlin:
class Solution {
    fun fib(n:Int):Int{
        var first=0;
        var second=1;
        repeat(n){
            val next=first+second;
            first=second;
            second=next
        };
        return first
    }
}

code.cpp:
class Solution {
    public: int fib(int n){
        int first=0,second=1;
        while(n--){
            int next=first+second;
            first=second;
            second=next;
        }
        return first;
    }
};
